import type { ClinicalSource, EvidenceClaim, QuestionVariant } from './pilot-schema';
import type { AnswerChoiceTimingRegistryEntry, CaseExhibit, SyntheticClinicalCase, TestedConcept } from './schema';
import packet from '../../../docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.json';
import ledger from '../../../docs/research/sources-question-intraop-anesthetic-intraoperative-crises-20261112.json';

/** Explicit-import authoring sidecar. Admission proposals are not runtime schema fields. */
export const INTRAOP_I11_DRAFT = {
  contentVersion: 'question-intraop-anesthetic-intraoperative-crises.2026-11-12.v1',
  reviewStatus: 'needs_clinician_review', aiAssistedDrafting: true, lastClinicianReview: null,
} as const;
export const INTRAOP_I11_REVISION_DRAFT = {
  ...INTRAOP_I11_DRAFT,
  contentVersion: 'question-intraop-anesthetic-intraoperative-crises.2026-11-12.v1.r1',
  revisionRound: 1,
} as const;

interface DraftChoice {
  id: string; exactChoiceId: string; label: string; rationale: string;
  temptation: string; counterfactual: string; claimIds: string[];
  timing: { kind: 'no_test' } | { kind: 'test'; timingProfileId: string };
}
interface DraftNode {
  contentVersion: string;
  id: string; slug: string; questionVariantId: string; conceptId: string;
  objective: string; conceptType: TestedConcept['conceptType']; task: string;
  key: string; choices: DraftChoice[]; explanation: string; claimIds: string[];
  currentUpdate: string; exhibit?: CaseExhibit; previousConceptId: string | null;
  conceptMeaning: string; conceptVersionReason: string;
  authorGate: Record<string, unknown>;
}
interface DraftCase {
  id: string; slug: string; name: string; ageYears: number; sexLabel: 'Female' | 'Male';
  chiefComplaint: string; presentation: string; nodes: DraftNode[];
  encounterMode: 'live_asc_or' | 'clinic_chart_review'; educationalTier: 1;
  currentAcuity: 'stable' | 'obvious_emergency'; recordedAcuity: 'obvious_emergency' | null;
  earliestFacilityStage: 0 | 3; requiredClinicalSetting: 'ambulatory_surgery' | 'clinic';
  requiredCapabilityIds: string[]; releasePointId: string; selectionConstraint: string;
  procedureContext: Record<string, unknown>;
}

export const INTRAOP_I11_PACKET = packet;
export const INTRAOP_I11_DEFINITIONS = packet.proposedCases as unknown as DraftCase[];
export const INTRAOP_I11_SOURCES = ledger.sources as unknown as ClinicalSource[];
export const INTRAOP_I11_CLAIMS = ledger.claims as unknown as EvidenceClaim[];
export const INTRAOP_I11_AUDIT = packet.audit;
export const INTRAOP_I11_FROZEN_REFERENCES = packet.freezeReferences;
export const INTRAOP_I11_STATEMENT_MAPPINGS = ledger.statementMappings;
export const INTRAOP_I11_REVIEW_REVISION = packet.independentReviewRevision;

const frozenPassIds = new Set(packet.independentReviewRevision.frozenPass.map(r => r.questionVariantId));
const originalQuestions = packet.independentReviewRevision.originalArtifacts.questions as unknown as QuestionVariant[];
const originalCases = packet.independentReviewRevision.originalArtifacts.cases as unknown as SyntheticClinicalCase[];
const originalAuthoringConcepts = packet.independentReviewRevision.originalArtifacts.authoringConcepts;

const textFor = (c: DraftCase, text: string) => text.split(c.name).join('{patientName}');
const claimsFor = (n: DraftNode) => [...new Set([...n.claimIds, ...n.choices.flatMap(ch => ch.claimIds)])];
const labelsFor = (claimIds: string[]) => {
  const sourceIds = new Set(INTRAOP_I11_CLAIMS.filter(c => claimIds.includes(c.id)).flatMap(c => c.sourceIds));
  return INTRAOP_I11_SOURCES.filter(s => sourceIds.has(s.id)).map(s => s.title);
};

export const INTRAOP_I11_QUESTIONS: QuestionVariant[] = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes.map(n => {
  if (frozenPassIds.has(n.questionVariantId)) return originalQuestions.find(q => q.id === n.questionVariantId)!;
  return {
  ...INTRAOP_I11_REVISION_DRAFT, contentVersion: n.contentVersion, id: n.questionVariantId, conceptId: n.conceptId,
  stem: textFor(c, n.task), explanation: n.explanation,
  ...(n.exhibit ? { exhibit: n.exhibit } : {}), supportingEvidenceClaimIds: claimsFor(n),
  answerChoices: n.choices.map(ch => ({ id: ch.exactChoiceId, label: ch.label,
    isCorrect: ch.id === n.key, rationale: ch.rationale,
    distractorRationale: ch.id === n.key ? null : ch.rationale })),
};
}));

export const INTRAOP_I11_CASES: SyntheticClinicalCase[] = INTRAOP_I11_DEFINITIONS.map(c => {
  const demographics = { ageYears: c.ageYears, sexLabel: c.sexLabel };
  const presentation = textFor(c, c.presentation);
  return {
    id: c.id, displayName: `${c.encounterMode === 'live_asc_or' ? 'ASC procedure' : 'Clinic record'}: ${c.name}`,
    patientDisplayName: c.name,
    patientPresentationVariantId: `presentation.intraop.i11.${c.slug}.v1`,
    prototypeDemographics: demographics, chiefComplaint: c.chiefComplaint, presentation,
    // This existing schema field names a finite profile, not clinician approval.
    approvedInstantiationProfiles: [{ id: `profile.intraop.i11.${c.slug}.v1`,
      prototypeDemographics: demographics, chiefComplaint: c.chiefComplaint, presentation }],
    releasePointId: c.releasePointId, tutorialEligible: false, routineEligible: true,
    earliestFacilityStage: c.earliestFacilityStage, requiredClinicalSetting: c.requiredClinicalSetting,
    requiredCapabilityIds: [...c.requiredCapabilityIds], rewardTierId: 'reward.clinic_basic',
    sourceLabels: labelsFor(c.nodes.flatMap(claimsFor)),
    decisionNodes: c.nodes.map((n, index) => {
      if (frozenPassIds.has(n.questionVariantId)) {
        return originalCases.flatMap(c => c.decisionNodes).find(before => before.questionVariantId === n.questionVariantId)!;
      }
      const q = INTRAOP_I11_QUESTIONS.find(q => q.id === n.questionVariantId)!;
      const sourceLabels = labelsFor(claimsFor(n));
      return {
        id: n.id, questionVariantId: q.id, primaryConceptId: n.conceptId, stem: q.stem,
        ...(n.currentUpdate ? { currentUpdate: textFor(c, n.currentUpdate) } : {}),
        ...(n.exhibit ? { exhibit: n.exhibit } : {}), shuffleAnswers: true,
        answerChoices: q.answerChoices.map(ch => ({ id: ch.id, label: ch.label,
          isCorrect: ch.isCorrect, rationale: ch.rationale!, serviceRequest: null })),
        explanation: q.explanation, sourceLabels, resultGateAfter: null,
        terminalDispositions: index === c.nodes.length - 1 ? q.answerChoices.filter(ch => !ch.isCorrect).map(ch => ({
          answerChoiceId: ch.id, kind: 'no_terminal_outcome' as const,
          consequenceNarrative: 'Review this decision; no patient outcome or rescue intervention is executed by this consult.',
          clinicalRationale: ch.rationale!, sourceLabels,
        })) : [],
      };
    }),
    learningSummary: c.nodes.map(n => n.explanation).join(' '),
  };
});

export const INTRAOP_I11_TESTED_CONCEPTS: TestedConcept[] = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes.map(n => ({
  id: n.conceptId, displayName: n.objective, learningObjective: n.objective,
  conceptType: n.conceptType, earliestFacilityStage: c.earliestFacilityStage,
})));
export const INTRAOP_I11_AUTHORING_CONCEPTS = INTRAOP_I11_TESTED_CONCEPTS.map(c => {
  const n = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes).find(n => n.conceptId === c.id)!;
  if (frozenPassIds.has(n.questionVariantId)) return originalAuthoringConcepts.find(before => before.id === c.id)!;
  return { ...INTRAOP_I11_REVISION_DRAFT, contentVersion: n.contentVersion, ...c, previousConceptId: n.previousConceptId,
    conceptMeaning: n.conceptMeaning, conceptVersionReason: n.conceptVersionReason,
    evidenceClaimIds: claimsFor(n), historyMigration: 'None; preserve all historical definitions and FSRS identities.' };
});

export const INTRAOP_I11_CASE_REVIEWS = INTRAOP_I11_DEFINITIONS.map(c => ({
  ...INTRAOP_I11_REVISION_DRAFT, caseId: c.id, educationalTier: c.educationalTier,
  acuity: c.currentAcuity, recordedAcuity: c.recordedAcuity, encounterMode: c.encounterMode,
  earliestFacilityStage: c.earliestFacilityStage, requiredClinicalSetting: c.requiredClinicalSetting,
  requiredCapabilityIds: c.requiredCapabilityIds, selectionConstraint: c.selectionConstraint,
  finiteProfileCount: 1, profileApproval: 'needs_clinician_review',
  generationConstraint: 'Freeze age, sex, source patient, exposure, observed treatment and checkpoint together.',
}));

export const INTRAOP_I11_PROCEDURE_CONTEXT_PROPOSALS = INTRAOP_I11_DEFINITIONS.map(c => ({
  ...INTRAOP_I11_REVISION_DRAFT, caseId: c.id, ...c.procedureContext,
}));
export const INTRAOP_I11_AUTHOR_CHECKS = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes.map(n => ({
  ...INTRAOP_I11_DRAFT, contentVersion: n.contentVersion, caseId: c.id, nodeId: n.id, questionVariantId: n.questionVariantId,
  ...n.authorGate, distractorChecks: n.choices.filter(ch => ch.id !== n.key).map(ch => ({
    choiceId: ch.exactChoiceId, temptation: ch.temptation, whyLessAppropriate: ch.rationale,
    counterfactual: ch.counterfactual, claimIds: ch.claimIds,
  })),
})));

export const INTRAOP_I11_TIMING_ENTRIES: AnswerChoiceTimingRegistryEntry[] = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes.map(n => ({
  caseId: c.id, nodeId: n.id, questionVariantId: n.questionVariantId,
  classification: n.choices.some(ch => ch.timing.kind === 'test') ? {
    kind: 'test_choices' as const,
    choices: n.choices.map(ch => ({ choiceId: ch.exactChoiceId, choiceLabel: ch.label, timing: ch.timing })),
  } : { kind: 'no_test' as const },
})));
export const INTRAOP_I11_ORDER_PROPOSALS = INTRAOP_I11_DEFINITIONS.flatMap(c => c.nodes.map(n => {
  if (frozenPassIds.has(n.questionVariantId)) {
    return packet.independentReviewRevision.originalArtifacts.orders.find(before => before.questionVariantId === n.questionVariantId)!;
  }
  return {
  ...INTRAOP_I11_REVISION_DRAFT, contentVersion: n.contentVersion, caseId: c.id, nodeId: n.id, questionVariantId: n.questionVariantId,
  serviceRequest: null, resultGateAfter: null, execution: 'observation_consult_no_executed_orders',
  choices: n.choices.map(ch => ({ choiceId: ch.exactChoiceId, choiceLabel: ch.label, timing: ch.timing })),
  integrationDependency: 'Install exact accepted choice/label mappings only during manager integration; no testing alternative is offered in this packet.',
};
}));
export const INTRAOP_I11_SOURCE_LINKS = INTRAOP_I11_SOURCES.map(s => ({
  sourceId: s.id, label: s.title, href: s.officialUrl!, target: '_blank' as const,
  rel: 'noopener noreferrer' as const, referrerPolicy: 'no-referrer' as const,
}));
export const INTRAOP_I11_PREVIEW_RELEASE = {
  id: 'clinical.intraop.i11.2026-11-12.v1', schemaVersion: 1,
  publicationStatus: 'synthetic_unapproved_prototype',
  disclaimer: 'Synthetic authoring preview, not clinically approved. Exact independent review and manager admission are pending.',
  concepts: INTRAOP_I11_TESTED_CONCEPTS, cases: INTRAOP_I11_CASES,
} as const;
export const INTRAOP_I11_MANIFEST = {
  ...INTRAOP_I11_REVISION_DRAFT, scope: 'explicit_import_authoring_sidecar', pipelinePassed: false,
  clinicalApproval: false, managerAccepted: false, publicReleaseAuthorized: false,
  executableOrdersAdded: false, liveAdmissionAuthorized: false,
  keyOrderNotice: 'key shown first for review only; runtime options are randomized',
  counts: packet.counts, integrationDependencies: packet.integrationDependencies,
  frozenPassQuestionVariantIds: [...frozenPassIds],
};

import packet from "../../../docs/research/question-intraop-anorectal-eua-and-fistula-20261112.json";
import ledger from "../../../docs/research/sources-question-intraop-anorectal-eua-and-fistula-20261112.json";
import type { AuthoredClinicalRecord, ClinicalSource, EvidenceClaim, QuestionVariant } from "./pilot-schema";
import {
  answerChoiceTimingRegistryEntrySchema,
  caseExhibitSchema,
  decisionNodeSchema,
  syntheticClinicalCaseSchema,
  testedConceptSchema,
  type AnswerChoiceTimingRegistryEntry,
  type DecisionNode,
  type SyntheticClinicalCase,
  type TestedConcept,
} from "./schema";

/** Explicit-import authoring lane. Acceptance and family admission remain separate. */
export const INTRAOP_ANORECTAL_PACKET = packet;
export const INTRAOP_ANORECTAL_SOURCE_LEDGER = ledger;
export const INTRAOP_ANORECTAL_DRAFT = {
  contentVersion: packet.contentVersion,
  reviewStatus: "needs_clinician_review",
  aiAssistedDrafting: true,
  lastClinicianReview: null,
} as const;

export const INTRAOP_ANORECTAL_SOURCES = ledger.sources as ClinicalSource[];
export const INTRAOP_ANORECTAL_CLAIMS = ledger.evidenceClaims as EvidenceClaim[];
export const INTRAOP_ANORECTAL_AUDIT = packet.audit;
export const INTRAOP_ANORECTAL_ORDER_PROPOSALS = packet.testOrderProposals;
export const INTRAOP_ANORECTAL_PROCEDURE_CONTEXT_PROPOSALS = packet.procedureContextProposals;
export const INTRAOP_ANORECTAL_SOURCE_LINKS = packet.sourceLinkProposals;
export const INTRAOP_ANORECTAL_STATEMENT_MAPPINGS = packet.statementMappings;
export const INTRAOP_ANORECTAL_REVIEW_RESPONSE = packet.revisionRound1;
/** The reviewed definitions and prior timing tuples remain available unchanged. */
export const INTRAOP_ANORECTAL_ROUND0 = packet.revisionRound1.snapshot;
export const INTRAOP_ANORECTAL_RETAINED_ORDER_PROPOSALS = packet.retainedTestOrderProposals;
export const INTRAOP_ANORECTAL_RETAINED_TIMING_ENTRIES: AnswerChoiceTimingRegistryEntry[] =
  packet.retainedTimingProposals.map((entry) => answerChoiceTimingRegistryEntrySchema.parse(entry));

export const INTRAOP_ANORECTAL_QUESTIONS: QuestionVariant[] = packet.proposedNodes.map((item) => ({
  ...INTRAOP_ANORECTAL_DRAFT,
  contentVersion: item.contentVersion,
  id: item.questionVariantId,
  conceptId: item.conceptId,
  stem: item.task,
  ...(item.exhibit ? { exhibit: caseExhibitSchema.parse(item.exhibit) } : {}),
  answerChoices: item.choices.map((choice) => ({
    id: choice.id,
    label: choice.label,
    isCorrect: choice.isCorrect,
    rationale: choice.rationale,
    distractorRationale: choice.isCorrect ? null : choice.rationale,
  })),
  explanation: item.explanation,
  supportingEvidenceClaimIds: item.supportingEvidenceClaimIds,
}));

function labelsFor(claimIds: readonly string[]): string[] {
  const sourceIds = new Set(INTRAOP_ANORECTAL_CLAIMS
    .filter((claim) => claimIds.includes(claim.id)).flatMap((claim) => claim.sourceIds));
  return INTRAOP_ANORECTAL_SOURCES.filter((source) => sourceIds.has(source.id)).map((source) => source.title);
}

export const INTRAOP_ANORECTAL_NODES: DecisionNode[] = packet.proposedNodes.map((item) => {
  const question = INTRAOP_ANORECTAL_QUESTIONS.find((entry) => entry.id === item.questionVariantId)!;
  const composition = packet.caseCompositionProposals.find((entry) => entry.id === item.caseId)!;
  const sourceLabels = labelsFor(question.supportingEvidenceClaimIds);
  return decisionNodeSchema.parse({
    id: item.nodeId,
    questionVariantId: question.id,
    primaryConceptId: question.conceptId,
    currentUpdate: item.currentUpdate,
    stem: question.stem,
    ...(question.exhibit ? { exhibit: question.exhibit } : {}),
    answerChoices: question.answerChoices.map((choice) => ({
      id: choice.id,
      label: choice.label,
      isCorrect: choice.isCorrect,
      rationale: choice.rationale,
      serviceRequest: null,
    })),
    shuffleAnswers: true,
    explanation: question.explanation,
    sourceLabels,
    // These are observations and decisions. No chosen test is executed here.
    resultGateAfter: null,
    terminalDispositions: composition.nodeIds.at(-1) === item.nodeId
      ? question.answerChoices.filter((choice) => !choice.isCorrect).map((choice) => ({
        answerChoiceId: choice.id,
        kind: "no_terminal_outcome",
        consequenceNarrative: "Review the interpretation before continuing; this authoring draft simulates no patient outcome.",
        clinicalRationale: choice.rationale!,
        sourceLabels,
      })) : [],
  });
});

export const INTRAOP_ANORECTAL_TESTED_CONCEPTS: TestedConcept[] = packet.conceptDecisions.map((item) =>
  testedConceptSchema.parse({
    id: item.conceptId,
    displayName: item.objective,
    learningObjective: item.objective,
    earliestFacilityStage: item.earliestFacilityStage,
    conceptType: item.conceptType,
  }));

export interface IntraopAnorectalConceptProposal extends TestedConcept, AuthoredClinicalRecord {
  previousConceptId: string | null;
  conceptRelation: "new_meaning";
  relatedExistingConceptIds: string[];
  educationalTier: number;
  evidenceClaimIds: string[];
}

export const INTRAOP_ANORECTAL_CONCEPT_PROPOSALS: IntraopAnorectalConceptProposal[] =
  INTRAOP_ANORECTAL_TESTED_CONCEPTS.map((concept) => {
    const item = packet.conceptDecisions.find((entry) => entry.conceptId === concept.id)!;
    return {
      ...concept,
      ...INTRAOP_ANORECTAL_DRAFT,
      contentVersion: item.contentVersion,
      previousConceptId: item.previousConceptId,
      conceptRelation: "new_meaning",
      relatedExistingConceptIds: item.relatedExistingConceptIds,
      educationalTier: item.educationalTier,
      evidenceClaimIds: item.evidenceClaimIds,
    };
  });

export const INTRAOP_ANORECTAL_CASES: SyntheticClinicalCase[] = packet.caseCompositionProposals.map((item) => {
  const nodes = item.nodeIds.map((id) => INTRAOP_ANORECTAL_NODES.find((node) => node.id === id)!);
  return syntheticClinicalCaseSchema.parse({
    id: item.id,
    displayName: item.displayName,
    patientPresentationVariantId: item.patientPresentationVariantId,
    releasePointId: "release.l3.ambulatory",
    patientDisplayName: item.patientDisplayName,
    prototypeDemographics: item.prototypeDemographics,
    chiefComplaint: item.chiefComplaint,
    presentation: item.presentation,
    approvedInstantiationProfiles: [{
      id: item.profileId,
      prototypeDemographics: item.prototypeDemographics,
      chiefComplaint: item.chiefComplaint,
      presentation: item.presentation,
    }],
    tutorialEligible: false,
    // Activation requires an accepted, matched anorectal source procedure.
    routineEligible: false,
    earliestFacilityStage: item.earliestFacilityStage,
    requiredClinicalSetting: "ambulatory_surgery",
    requiredCapabilityIds: ["capability.ambulatory_or", "capability.staff.or_nurse", "capability.periop_recovery"],
    rewardTierId: "reward.clinic_basic",
    sourceLabels: [...new Set(nodes.flatMap((node) => node.sourceLabels))],
    decisionNodes: nodes,
    learningSummary: nodes.map((node) => node.explanation).join(" "),
  });
});

export const INTRAOP_ANORECTAL_CASE_REVIEWS = packet.caseReviews;
export const INTRAOP_ANORECTAL_TIMING_ENTRIES: AnswerChoiceTimingRegistryEntry[] = packet.timingProposals
  .map((entry) => answerChoiceTimingRegistryEntrySchema.parse(entry));

export const INTRAOP_ANORECTAL_INTEGRATION = {
  publicationStatus: "authoring_sidecar",
  ...INTRAOP_ANORECTAL_DRAFT,
  revisionRound: 1,
  independentReview: {
    path: packet.revisionRound1.reviewFile,
    sha256: packet.revisionRound1.reviewSha256,
    preservedPassQuestionVariantIds: packet.revisionRound1.passFreeze.map((record) => record.questionVariantId),
    returnedRevisionsAwaitingReview: packet.revisionRound1.nodeDispositions
      .filter((record) => record.inputVerdict !== "PASS").map((record) => record.questionVariantId),
  },
  managerAcceptance: null,
  admittedCaseIds: [],
  dependencies: packet.integrationDependencies,
  ownerApprovalsNeeded: packet.ownerApprovalsNeeded,
  withheldTeachingPoints: packet.withheldTeachingPoints,
} as const;

import packet from "../../../docs/research/question-intraop-parathyroid-localization-and-preservation-20261112.json";
import ledger from "../../../docs/research/sources-question-intraop-parathyroid-localization-and-preservation-20261112.json";
import type { AuthoredClinicalRecord, ClinicalSource, EvidenceClaim, QuestionVariant } from "./pilot-schema";
import {
  answerChoiceTimingRegistryEntrySchema,
  caseExhibitSchema,
  decisionNodeSchema,
  syntheticClinicalCaseSchema,
  testedConceptSchema,
  type AnswerChoiceTimingRegistryEntry,
  type DecisionNode,
  type SyntheticClinicalCase,
  type TestedConcept,
} from "./schema";

/** Explicit-import, unintegrated authoring sidecar. No shared registry mutation. */
export const I07_PACKET = packet;
export const I07_SOURCE_LEDGER = ledger;
export const I07_DRAFT = {
  contentVersion: packet.contentVersion,
  reviewStatus: "needs_clinician_review",
  aiAssistedDrafting: true,
  lastClinicianReview: null,
} as const;
export const I07_SOURCES = ledger.sources as ClinicalSource[];
export const I07_CLAIMS = ledger.evidenceClaims as EvidenceClaim[];
export const I07_AUDIT = packet.audit;
export const I07_SOURCE_LINKS = packet.sourceLinkProposals;
export const I07_ORDER_PROPOSALS = packet.testOrderProposals;
export const I07_PROCEDURE_CONTEXT_PROPOSALS = packet.procedureContextProposals;
export const I07_CASE_REVIEWS = packet.caseReviews;
export const I07_REVISION_ROUND1 = packet.revisionRound1;
/** Historical records remain available for frozen encounters and exact review. */
export const I07_REVIEWED_TIMING_ENTRIES = packet.revisionRound1.snapshot.reviewedBundle.timingEntries;
export const I07_REVIEWED_ORDER_PROPOSALS = packet.revisionRound1.snapshot.reviewedBundle.orderProposals;
export const I07_FROZEN_PASS_CONTEXTS: SyntheticClinicalCase[] = packet.revisionRound1.passFreeze
  .map(frozen => frozen.clinicalCase as unknown as SyntheticClinicalCase);

const frozenFor = (questionId: string) => packet.revisionRound1.passFreeze
  .find(frozen => frozen.questionVariantId === questionId);

export const I07_QUESTIONS: Array<QuestionVariant & { shuffleAnswers: true }> = packet.proposedNodes.map(item => {
  const frozen = frozenFor(item.questionVariantId);
  if (frozen) return frozen.question as unknown as QuestionVariant & { shuffleAnswers: true };
  return {
    ...I07_DRAFT,
    id: item.questionVariantId,
    conceptId: item.conceptId,
    stem: item.task,
    ...(item.exhibit ? { exhibit: caseExhibitSchema.parse(item.exhibit) } : {}),
    answerChoices: item.choices.map(choice => ({
      id: choice.id,
      label: choice.label,
      isCorrect: choice.isCorrect,
      rationale: choice.rationale,
      distractorRationale: choice.isCorrect ? null : choice.rationale,
    })),
    shuffleAnswers: true,
    explanation: item.explanation,
    supportingEvidenceClaimIds: item.supportingEvidenceClaimIds,
  };
});

const sourceLabelsFor = (claimIds: readonly string[]) => {
  const ids = new Set(I07_CLAIMS.filter(claim => claimIds.includes(claim.id)).flatMap(claim => claim.sourceIds));
  return I07_SOURCES.filter(source => ids.has(source.id)).map(source => source.title);
};

export const I07_NODES: DecisionNode[] = packet.proposedNodes.map(item => {
  const frozen = frozenFor(item.questionVariantId);
  if (frozen) return frozen.node as unknown as DecisionNode;
  const question = I07_QUESTIONS.find(entry => entry.id === item.questionVariantId)!;
  const composition = packet.caseCompositionProposals.find(entry => entry.id === item.caseId)!;
  const sourceLabels = sourceLabelsFor(question.supportingEvidenceClaimIds);
  return decisionNodeSchema.parse({
    id: item.nodeId,
    questionVariantId: question.id,
    primaryConceptId: question.conceptId,
    currentUpdate: item.currentUpdate,
    stem: question.stem,
    ...(question.exhibit ? { exhibit: question.exhibit } : {}),
    answerChoices: question.answerChoices.map(choice => ({
      id: choice.id, label: choice.label, isCorrect: choice.isCorrect,
      rationale: choice.rationale, serviceRequest: null,
    })),
    shuffleAnswers: true,
    explanation: question.explanation,
    sourceLabels,
    resultGateAfter: null,
    terminalDispositions: composition.nodeIds.at(-1) === item.nodeId
      ? question.answerChoices.filter(choice => !choice.isCorrect).map(choice => ({
        answerChoiceId: choice.id,
        kind: "no_terminal_outcome",
        consequenceNarrative: "The proposed plan differs from the observed tissue or specimen findings; review the explanation.",
        clinicalRationale: choice.rationale!,
        sourceLabels,
      })) : [],
  });
});

export const I07_CONCEPTS: TestedConcept[] = packet.conceptDecisions.map(item => {
  const frozen = packet.revisionRound1.passFreeze.find(entry => entry.conceptId === item.conceptId);
  if (frozen) return frozen.concept as unknown as TestedConcept;
  return testedConceptSchema.parse({
    id: item.conceptId,
    displayName: packet.proposedNodes.find(node => node.conceptId === item.conceptId)!.title,
    learningObjective: item.objective,
    earliestFacilityStage: item.earliestFacilityStage,
    conceptType: item.conceptType,
  });
});

export interface I07ConceptProposal extends TestedConcept, AuthoredClinicalRecord {
  previousConceptId: string | null;
  conceptRelation: "new_meaning" | "existing_meaning_variant";
