    stem: n.task, shuffleAnswers: true, explanation: n.explanation,
    ...('exhibit' in n ? { exhibit: n.exhibit as CaseExhibit } : {}),
    supportingEvidenceClaimIds: allClaimsFor(n),
    answerChoices: n.choices.map(c => ({
      id: c.id, label: c.label, isCorrect: c.isCorrect,
