  if (!clinicalCase) throw new Error(`I27 node has no case: ${n.id}`);
  const sourceLabels = labelsFor(allClaimsFor(n));
  return decisionNodeSchema.parse({
    id: n.id, questionVariantId: question.id, primaryConceptId: question.conceptId,
    currentUpdate: n.currentUpdate, stem: question.stem, shuffleAnswers: true,
