      id: c.id, label: c.label, isCorrect: c.isCorrect, rationale: c.rationale, serviceRequest: null,
    })),
    explanation: question.explanation, sourceLabels, resultGateAfter: null,
    terminalDispositions: clinicalCase.nodeIds.at(-1) === n.id
      ? question.answerChoices.filter(c => !c.isCorrect).map(c => ({
        answerChoiceId: c.id, kind: 'no_terminal_outcome',
